"""Checks how your tests are organized and configured. Do not edit this file.

Tests are code too: pytest can list them (--collect-only) and the configuration
is a file anyone can read. That is what these checks do.
"""

import os
import subprocess
import sys
import tomllib
from pathlib import Path

LAB = Path(__file__).resolve().parent.parent
RULES = {"too-short", "no-digit", "no-upper", "no-lower", "whitespace", "common"}


def collect(*args: str) -> list[str]:
    env = {**os.environ, "PYTHONIOENCODING": "utf-8"}
    env.pop("PASSWORDS_MUTANT", None)
    result = subprocess.run(
        [sys.executable, "-m", "pytest", "tests/test_policy.py", "--collect-only", "-q", "-p", "no:cacheprovider", *args],
        cwd=LAB, env=env, capture_output=True, text=True, encoding="utf-8", errors="replace",
    )
    return [line for line in result.stdout.splitlines() if "::" in line]


def pytest_table() -> dict:
    return tomllib.loads((LAB / "pyproject.toml").read_text(encoding="utf-8")).get("tool", {}).get("pytest", {})


# Task 1


def test_rules_are_one_parametrized_test_with_readable_ids():
    ids = {line.split("[", 1)[1].rstrip("]") for line in collect() if "::test_each_rule[" in line}
    missing = RULES - ids
    assert not missing, f"test_each_rule needs one case per rule with these ids: {sorted(missing)}"


# Task 3


def test_configuration_uses_the_native_toml_table():
    table = pytest_table()
    assert "ini_options" not in table, "Move the settings from [tool.pytest.ini_options] to [tool.pytest]"
    assert table.get("pythonpath") == ["."], "In [tool.pytest], pythonpath is a list: [\".\"]"


def test_strict_options_are_on():
    table = pytest_table()
    assert table.get("strict_markers") is True, "Set strict_markers = true in [tool.pytest]"
    assert table.get("strict_xfail") is True, "Set strict_xfail = true in [tool.pytest]"


def test_slow_marker_is_registered_and_used():
    markers = pytest_table().get("markers", [])
    assert any(marker.split(":")[0].strip() == "slow" for marker in markers), "Register the 'slow' marker"
    assert collect("-m", "slow"), "Mark at least one test with @pytest.mark.slow"
